/*  HORIZON LIBRE — procedural synth audio (no external assets)       */
/* ------------------------------------------------------------------ */

const midi = n => 440 * Math.pow(2, (n - 69) / 12)

export class GameAudio {
  constructor() {
    this.ctx = null
    this.ready = false
    this.muted = false
    this.master = null
    this.engineBus = null
    this.musicBus = null
    this.sfxBus = null
    this.engine = null
    this.wind = null
    this.tire = null
    this.module = 0
    this.nextStep = 0
    this.step = 0
    this.tempo = 94
    this.musicOn = true
    this.engineOn = false
    this.boost = false
    this.delay = null
  }

  async init() {
    if (this.ready) return
    const AC = window.AudioContext || window.webkitAudioContext
    if (!AC) return
    this.ctx = new AC()
    await this.ctx.resume().catch(() => {})
    this.master = this.ctx.createGain()
    this.master.gain.value = this.muted ? 0 : 0.72
    this.master.connect(this.ctx.destination)

    this.engineBus = this.ctx.createGain(); this.engineBus.gain.value = 0.0
    this.musicBus = this.ctx.createGain(); this.musicBus.gain.value = 0.16
    this.sfxBus = this.ctx.createGain(); this.sfxBus.gain.value = 0.35
    this.engineBus.connect(this.master)
    this.musicBus.connect(this.master)
    this.sfxBus.connect(this.master)

    // echo for the music
    this.delay = this.ctx.createDelay(1.0)
    this.delay.delayTime.value = 0.29
    const fb = this.ctx.createGain(); fb.gain.value = 0.23
    const wet = this.ctx.createGain(); wet.gain.value = 0.28
    this.delay.connect(fb); fb.connect(this.delay)
    this.delay.connect(wet); wet.connect(this.musicBus)

    this.buildEngine()
    this.buildWind()
    this.nextStep = this.ctx.currentTime + 0.1
    this.ready = true
  }

  noiseBuffer(seconds = 2) {
    const len = Math.floor(this.ctx.sampleRate * seconds)
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate)
    const data = buf.getChannelData(0)
    let last = 0
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1
      last = last * 0.35 + white * 0.65
      data[i] = last
    }
    return buf
  }

  buildEngine() {
    const ctx = this.ctx
    const osc1 = ctx.createOscillator(); osc1.type = 'sawtooth'; osc1.frequency.value = 70
    const osc2 = ctx.createOscillator(); osc2.type = 'square'; osc2.frequency.value = 35
    const gain1 = ctx.createGain(); gain1.gain.value = 0.22
    const gain2 = ctx.createGain(); gain2.gain.value = 0.08
    const filter = ctx.createBiquadFilter(); filter.type = 'lowpass'; filter.frequency.value = 700; filter.Q.value = 1.4
    const bus = ctx.createGain(); bus.gain.value = 0.0
    osc1.connect(gain1); gain1.connect(filter)
    osc2.connect(gain2); gain2.connect(filter)
    filter.connect(bus); bus.connect(this.engineBus)
    osc1.start(); osc2.start()
    this.engine = { osc1, osc2, filter, bus, gain1, gain2 }

    const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer(2); src.loop = true
    const filt = ctx.createBiquadFilter(); filt.type = 'bandpass'; filt.frequency.value = 1700; filt.Q.value = 3.5
    const g = ctx.createGain(); g.gain.value = 0
    src.connect(filt); filt.connect(g); g.connect(this.engineBus)
    src.start()
    this.tire = { src, filt, gain: g }
  }

  buildWind() {
    const ctx = this.ctx
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer(3); src.loop = true
    const filt = ctx.createBiquadFilter(); filt.type = 'lowpass'; filt.frequency.value = 420; filt.Q.value = 0.6
    const g = ctx.createGain(); g.gain.value = 0
    src.connect(filt); filt.connect(g); g.connect(this.master)
    src.start()
    this.wind = { gain: g, filter: filt }
  }

  updateEngine(rpm = 900, throttle = 0, speed = 0, slip = 0, offroad = false, boost = false, active = false) {
    if (!this.ready) return
    const t = this.ctx.currentTime
    const f = Math.max(24, rpm / 60 * 3.1)
    const targetOn = active ? 0.055 + throttle * 0.11 : 0.0
    this.engine.bus.gain.setTargetAtTime(targetOn * (boost ? 1.35 : 1), t, 0.07)
    this.engine.osc1.frequency.setTargetAtTime(f, t, 0.035)
    this.engine.osc2.frequency.setTargetAtTime(f * 0.5 + 1.4, t, 0.05)
    this.engine.filter.frequency.setTargetAtTime(320 + throttle * 1300 + Math.min(900, rpm / 9), t, 0.06)
    this.engine.filter.Q.setTargetAtTime(boost ? 3.2 : 1.2, t, 0.1)
    this.engine.gain2.gain.setTargetAtTime(boost ? 0.14 : 0.07, t, 0.08)

    const squeal = active ? Math.min(0.16, Math.abs(slip) * 0.022) : 0
    this.tire.gain.gain.setTargetAtTime(squeal, t, 0.05)
    this.tire.filt.frequency.setTargetAtTime(1200 + Math.abs(slip) * 90, t, 0.08)

    const windVol = active ? Math.min(0.2, (speed / 80) ** 2 * 0.18 + (offroad ? 0.02 : 0)) : 0.012
    this.wind.gain.gain.setTargetAtTime(windVol, t, 0.15)
    this.wind.filter.frequency.setTargetAtTime(300 + speed * 7, t, 0.2)
  }

  click(pitch = 700) {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    const o = ctx.createOscillator(); o.type = 'triangle'
    const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.14, t + 0.005); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.1)
    o.frequency.setValueAtTime(pitch, t); o.frequency.exponentialRampToValueAtTime(pitch * 0.65, t + 0.09)
    o.connect(g); g.connect(this.sfxBus); o.start(t); o.stop(t + 0.12)
  }

  chime() {
    if (!this.ready) return
    const ctx = this.ctx, t = ctx.currentTime
    ;[0, 4, 7, 12].forEach((n, i) => {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = midi(72 + n)
      const g = ctx.createGain(); g.gain.setValueAtTime(0, t + i * 0.07); g.gain.linearRampToValueAtTime(0.08, t + i * 0.07 + 0.02); g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.07 + 0.7)
      o.connect(g); g.connect(this.sfxBus); o.start(t + i * 0.07); o.stop(t + i * 0.07 + 0.8)
    })
  }

  note(freq, time, duration, gain, type = 'triangle', dest = null, filterHz = 2800) {
    const ctx = this.ctx
    const o = ctx.createOscillator(); o.type = type; o.frequency.value = freq
    const g = ctx.createGain()
    g.gain.setValueAtTime(0.0001, time)
    g.gain.linearRampToValueAtTime(gain, time + 0.015)
    g.gain.exponentialRampToValueAtTime(0.0001, time + duration)
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = filterHz
    o.connect(f); f.connect(g); g.connect(dest || this.musicBus)
    o.start(time); o.stop(time + duration + 0.05)
  }

  scheduleMusic() {
    if (!this.ready || !this.musicOn) return
    const ctx = this.ctx
    const stepDur = (60 / this.tempo) / 4
    while (this.nextStep < ctx.currentTime + 0.25) {
      const s = this.step % 64
      const bar = Math.floor(s / 16) % 4
      const chord = bar === 0 ? [57, 60, 64, 69] : bar === 1 ? [53, 57, 60, 65] : bar === 2 ? [48, 52, 55, 60] : [55, 59, 62, 67]
      const root = chord[0] - 12
      if (s % 16 === 0) {
        // warm pad
        chord.forEach((n, i) => this.note(midi(n), this.nextStep, 4.2, 0.022, i === 0 ? 'triangle' : 'sawtooth', null, 600 + i * 120))
      }
      if (s % 8 === 0) this.note(midi(root - 12 + (bar === 2 ? 0 : 0)), this.nextStep, 0.55, 0.11, 'sawtooth', this.delay, 420)
      if (s % 8 === 4) this.note(midi(root - 5), this.nextStep, 0.32, 0.055, 'sine', this.delay, 500)
      if (s % 2 === 1) {
        const arp = chord[(Math.floor(s / 2) + bar) % 4] + 12
        this.note(midi(arp), this.nextStep, 0.18, 0.026, 'triangle', this.delay, 3200)
      }
      if (s === 60) this.note(midi(chord[2] + 12), this.nextStep, 0.9, 0.03, 'sine', this.delay, 4000)
      this.nextStep += stepDur
      this.step++
    }
  }

  update() {
    if (!this.ready) return
    this.scheduleMusic()
  }

  setMuted(muted) {
    this.muted = muted
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.72, this.ctx.currentTime, 0.05)
  }

  setMusic(on) {
    this.musicOn = on
    if (this.musicBus) this.musicBus.gain.setTargetAtTime(on ? 0.16 : 0, this.ctx.currentTime, 0.2)
  }
}

/* ------------------------------------------------------------------ */
/*  HORIZON LIBRE — interface                                           */
/* ------------------------------------------------------------------ */
:root {
  --ink: #0a0e16;
  --ink-2: #101725;
  --paper: #f4f0e6;
  --muted: rgba(244, 240, 230, 0.56);
  --pink: #ff2d7a;
  --cyan: #23e6ff;
  --lime: #d7ff3f;
  --orange: #ff7a3d;
  --line: rgba(255, 255, 255, 0.14);
  --panel: linear-gradient(150deg, rgba(13, 18, 29, 0.88), rgba(9, 13, 22, 0.62));
  --display: 'Barlow Condensed', 'Arial Narrow', Impact, sans-serif;
  --body: 'Barlow', 'Helvetica Neue', Arial, sans-serif;
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.45);
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: #120b17; }
body {
  font-family: var(--body);
  color: var(--paper);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}
#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; }
#scene canvas { display: block; width: 100% !important; height: 100% !important; outline: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
.hidden { display: none !important; }
.muted { color: var(--muted); font-weight: 400; }
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 22px; height: 21px; padding: 0 6px; margin-right: 2px;
  font: 600 11px/1 var(--body); letter-spacing: .04em;
  color: rgba(255,255,255,.84);
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 4px;
  box-shadow: inset 0 -1px 0 rgba(0,0,0,.35);
}

/* film grain + vignette over the 3D scene, beneath UI */
#fx-grain, #fx-vignette { position: absolute; inset: 0; pointer-events: none; z-index: 2; }
#fx-grain {
  opacity: .055; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 240 240' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E");
  background-size: 240px 240px;
}
#fx-vignette {
  background:
    radial-gradient(ellipse at 50% 44%, transparent 40%, rgba(5, 7, 13, 0.34) 100%),
    linear-gradient(to bottom, rgba(7, 9, 16, 0.32), transparent 16%, transparent 74%, rgba(5, 8, 14, 0.52));
}
.layer { position: absolute; inset: 0; z-index: 5; }
.screen { padding: max(22px, env(safe-area-inset-top)) max(28px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(28px, env(safe-area-inset-left)); }

/* ----------------------------- loading ---------------------------- */
#loading {
  display: grid; place-items: center; z-index: 50;
  background:
    radial-gradient(circle at 70% 30%, rgba(255, 86, 69, .24), transparent 45%),
    radial-gradient(circle at 18% 82%, rgba(35, 230, 255, .13), transparent 40%),
    linear-gradient(160deg, #160d1c 0%, #0a0e16 68%);
}
#loading::after {
  content: ''; position: absolute; inset: 0;
  background-image: linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.025) 1px, transparent 1px);
  background-size: 72px 72px;
  mask-image: radial-gradient(circle at 50% 45%, black, transparent 68%);
}
.loading-wrap { position: relative; width: min(620px, 84vw); z-index: 1; }
.loading-mark { display: flex; align-items: flex-end; gap: 6px; height: 46px; margin-bottom: 20px; }
.loading-mark span { display: block; width: 16px; height: 26px; background: var(--pink); transform: skewX(-24deg); animation: markPulse 1.1s ease-in-out infinite alternate; }
.loading-mark span:nth-child(2) { height: 40px; background: var(--cyan); animation-delay: .18s; }
.loading-mark span:nth-child(3) { height: 18px; background: var(--lime); animation-delay: .36s; }
@keyframes markPulse { from { transform: skewX(-24deg) scaleY(.7); opacity: .65; } to { transform: skewX(-24deg) scaleY(1); opacity: 1; } }
.eyebrow { display: flex; align-items: center; gap: 10px; margin: 0 0 10px; color: var(--lime); font: 700 11px/1 var(--body); letter-spacing: .26em; text-transform: uppercase; }
.eyebrow .line { display: inline-block; width: 34px; height: 2px; background: var(--pink); }
.load-title { margin: 0; font: 800 74px/.82 var(--display); letter-spacing: -.02em; text-transform: uppercase; }
.load-title em { color: transparent; -webkit-text-stroke: 1.5px rgba(244,240,230,.75); font-style: normal; }
.load-bar { height: 3px; margin: 38px 0 10px; background: rgba(255,255,255,.11); overflow: hidden; }
.load-bar i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, var(--pink), var(--orange), var(--lime)); box-shadow: 0 0 16px rgba(255,45,122,.7); transition: width .28s ease; }
.load-row { display: flex; justify-content: space-between; color: var(--muted); font: 600 11px/1 var(--body); letter-spacing: .16em; text-transform: uppercase; }
.load-tip { position: absolute; right: 0; bottom: -74px; max-width: 340px; margin: 0; color: rgba(244,240,230,.42); font-size: 12px; line-height: 1.5; text-align: right; }
.loading-stripes { position: absolute; right: -60px; top: 0; width: 26vw; height: 100%; transform: skewX(-16deg); background: repeating-linear-gradient(90deg, rgba(255,45,122,.12) 0 3px, transparent 3px 28px); mask-image: linear-gradient(to bottom, transparent, black 30%, transparent 90%); }

/* ------------------------------ title ----------------------------- */
#title {
  z-index: 10;
  background:
    linear-gradient(100deg, rgba(7, 10, 18, 0.76) 0%, rgba(7, 10, 18, 0.3) 38%, transparent 60%),
    linear-gradient(to top, rgba(7,10,18,.82) 0%, transparent 34%);
}
.topbar { position: absolute; top: max(26px, env(safe-area-inset-top)); left: max(34px, env(safe-area-inset-left)); right: max(34px, env(safe-area-inset-right)); display: flex; align-items: center; justify-content: space-between; }
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark { display: flex; align-items: flex-end; gap: 4px; height: 32px; }
.brand-mark i { display: block; width: 10px; height: 18px; background: var(--paper); transform: skewX(-24deg); }
.brand-mark i:nth-child(2) { height: 29px; background: var(--pink); }
.brand-mark i:nth-child(3) { height: 13px; background: var(--cyan); }
.brand strong { display: block; font: 800 21px/.9 var(--display); letter-spacing: .08em; text-transform: uppercase; }
.brand strong span { color: var(--pink); }
.brand small { display: block; margin-top: 5px; color: var(--muted); font: 600 9px/1 var(--body); letter-spacing: .34em; }
.top-actions { display: flex; align-items: center; gap: 10px; }
.chip-btn { display: flex; align-items: center; gap: 9px; height: 36px; padding: 0 15px; color: rgba(255,255,255,.8); font: 600 10px/1 var(--body); letter-spacing: .14em; border: 1px solid var(--line); background: rgba(8,12,20,.44); }
.chip-btn:hover { border-color: rgba(255,255,255,.4); color: #fff; }
.chip-btn .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--lime); box-shadow: 0 0 10px var(--lime); }
.chip-btn .dot.sun { background: var(--orange); box-shadow: 0 0 10px var(--orange); }
.round-btn { width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid var(--line); background: rgba(8,12,20,.44); color: rgba(255,255,255,.82); font: 700 15px/1 var(--body); transition: .2s; }
.round-btn:hover { border-color: var(--pink); color: #fff; background: rgba(255,45,122,.13); }
.hero { position: absolute; left: max(5vw, 38px); bottom: 20vh; max-width: 760px; }
.hero .eyebrow { margin-bottom: 18px; }
.hero-title { display: flex; flex-direction: column; margin: 0; font: italic 800 clamp(74px, 11.4vw, 176px)/.76 var(--display); letter-spacing: -.015em; text-transform: uppercase; filter: drop-shadow(0 20px 40px rgba(0,0,0,.46)); }
.hero-title .outline { color: transparent; -webkit-text-stroke: 2px rgba(244,240,230,.9); letter-spacing: .01em; }
.hero-title .fill { color: var(--paper); background: linear-gradient(92deg, var(--paper) 14%, #ffd7a4 52%, var(--orange) 96%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.hero-sub { margin: 22px 0 28px; color: rgba(244,240,230,.68); font: 500 13px/1.5 var(--body); letter-spacing: .07em; }
.hero-actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.btn { position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 10px; height: 50px; padding: 0 28px; font: 700 12px/1 var(--body); letter-spacing: .18em; text-transform: uppercase; transition: .18s ease; }
.btn-primary { color: #0a0e16; background: var(--lime); clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px); font-weight: 800; }
.btn-primary:hover { background: #fff36b; transform: translateY(-2px); }
.btn-ghost { border: 1px solid rgba(255,255,255,.28); background: rgba(9,13,22,.48); color: rgba(255,255,255,.85); }
.btn-ghost:hover { border-color: var(--cyan); color: #fff; background: rgba(35,230,255,.09); transform: translateY(-2px); }
.btn .k { display: inline-flex; align-items: center; justify-content: center; width: 18px; height: 18px; border: 1px solid rgba(255,255,255,.28); font-size: 9px; opacity: .7; }
.btn.small { height: 40px; padding: 0 18px; font-size: 10px; }
.hero-meta { display: flex; align-items: center; gap: 15px; margin-top: 26px; color: rgba(244,240,230,.48); font: 500 10px/1 var(--body); letter-spacing: .13em; text-transform: uppercase; }
.hero-meta b { color: var(--paper); font-weight: 700; }
.hero-meta .sep { color: var(--pink); }
.car-card {
  position: absolute; right: max(4vw, 36px); bottom: 15vh; width: 300px; padding: 18px 20px 16px;
  background: linear-gradient(150deg, rgba(10,14,23,.78), rgba(10,14,23,.36));
  border: 1px solid var(--line); border-left: 2px solid var(--pink);
  backdrop-filter: blur(12px);
}
.car-card::before { content: ''; position: absolute; top: 0; left: 0; width: 42%; height: 2px; background: var(--cyan); }
.car-card-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 15px; }
.class-badge { display: inline-flex; align-items: center; gap: 5px; padding: 4px 9px; color: #0a0e16; background: var(--lime); font: 800 11px/1 var(--body); letter-spacing: .08em; }
.car-tag { color: rgba(255,255,255,.5); font: 600 9px/1 var(--body); letter-spacing: .12em; text-transform: uppercase; }
.car-card h2 { margin: 0; font: 800 32px/.95 var(--display); text-transform: uppercase; letter-spacing: .01em; }
.car-year { margin: 6px 0 16px; color: var(--muted); font: 500 10px/1 var(--body); letter-spacing: .16em; text-transform: uppercase; }
.stat-list { display: grid; gap: 7px; }
.stat { display: grid; grid-template-columns: 66px 1fr 22px; align-items: center; gap: 9px; }
.stat span { color: rgba(255,255,255,.46); font: 600 8px/1 var(--body); letter-spacing: .12em; text-transform: uppercase; }
.stat b { color: rgba(255,255,255,.66); font: 700 10px/1 var(--body); text-align: right; }
.bar { display: flex; gap: 2px; }
.bar i { display: block; flex: 1; height: 4px; background: rgba(255,255,255,.12); transform: skewX(-18deg); }
.bar i.on { background: var(--lime); box-shadow: 0 0 8px rgba(215,255,63,.35); }
.car-card .bar i.on { background: var(--cyan); box-shadow: 0 0 8px rgba(35,230,255,.3); }
.swatches { display: flex; gap: 6px; margin: 17px 0 14px; }
.swatch { width: 19px; height: 19px; border: 1px solid rgba(255,255,255,.22); border-radius: 50%; cursor: pointer; transition: .15s; }
.swatch:hover { transform: scale(1.16); }
.swatch.active { outline: 2px solid var(--paper); outline-offset: 2px; }
.text-btn { display: flex; align-items: center; justify-content: space-between; width: 100%; padding: 10px 0 0; border-top: 1px solid var(--line); color: rgba(255,255,255,.72); font: 700 9px/1 var(--body); letter-spacing: .16em; }
.text-btn:hover { color: var(--cyan); }
.text-btn span { font-size: 14px; }
.title-foot { position: absolute; left: max(5vw, 38px); right: max(4vw, 36px); bottom: max(20px, env(safe-area-inset-bottom)); display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.controls-line { display: flex; flex-wrap: wrap; gap: 16px; color: rgba(255,255,255,.42); font: 500 10px/1 var(--body); letter-spacing: .03em; }
.controls-line span { display: flex; align-items: center; gap: 4px; }
.credit-line { color: rgba(255,255,255,.26); font: 600 8px/1 var(--body); letter-spacing: .15em; text-align: right; }

/* ------------------------------- HUD ------------------------------ */
#hud { z-index: 8; pointer-events: none; }
#hud button { pointer-events: auto; }
.panel { background: var(--panel); border: 1px solid var(--line); box-shadow: var(--shadow); backdrop-filter: blur(10px); }
.hud-top-left { position: absolute; top: max(24px, env(safe-area-inset-top)); left: max(26px, env(safe-area-inset-left)); display: flex; flex-direction: column; gap: 10px; }
.event-chip { display: flex; align-items: center; gap: 11px; height: 48px; padding: 0 16px; border-left: 2px solid var(--lime); }
.event-icon { color: var(--lime); font-size: 13px; }
.event-chip b { display: block; font: 700 11px/1 var(--body); letter-spacing: .16em; }
.event-chip small { display: block; margin-top: 4px; color: var(--muted); font: 600 8px/1 var(--body); letter-spacing: .18em; }
.race-panel { width: 296px; padding: 12px 14px; }
.race-row { display: flex; align-items: center; justify-content: space-between; font: 600 10px/1 var(--body); letter-spacing: .05em; }
.race-row b { font-size: 14px; font-variant-numeric: tabular-nums; }
.race-row.small { margin-top: 7px; color: var(--muted); font-size: 8px; letter-spacing: .16em; }
.race-progress { height: 2px; margin-top: 10px; background: rgba(255,255,255,.12); }
.race-progress i { display: block; width: 0; height: 100%; background: var(--lime); transition: width .25s; }
.hud-top-right { position: absolute; top: max(24px, env(safe-area-inset-top)); right: max(26px, env(safe-area-inset-right)); display: flex; flex-direction: column; gap: 9px; align-items: flex-end; }
.minimap { width: 218px; padding: 8px 8px 6px; position: relative; }
.map-head { display: flex; justify-content: space-between; padding: 0 2px 6px; color: rgba(255,255,255,.4); font: 700 8px/1 var(--body); letter-spacing: .2em; }
#minimap { display: block; width: 200px; height: 200px; background: #0d1a24; }
.map-north { position: absolute; top: 25px; left: 50%; transform: translateX(-50%); color: rgba(255,255,255,.5); font: 700 8px/1 var(--body); }
.wallet { display: flex; align-items: center; justify-content: space-between; width: 218px; padding: 9px 11px; }
.wallet > div:first-child { display: flex; align-items: center; gap: 7px; }
.coin { display: inline-grid; place-items: center; width: 17px; height: 17px; border-radius: 50%; background: var(--lime); color: #0a0e16; font: 800 11px/1 var(--body); }
.wallet b { font: 700 13px/1 var(--body); letter-spacing: .04em; }
.wallet-sub { color: var(--muted); font: 600 8px/1 var(--body); letter-spacing: .1em; }
.wallet-sub span { color: var(--cyan); font-size: 10px; }
.checkpoint-arrow { position: absolute; top: max(88px, calc(env(safe-area-inset-top) + 70px)); left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 11px; padding: 9px 16px; background: rgba(9,13,22,.6); border: 1px solid var(--line); backdrop-filter: blur(8px); }
.cp-arrow-icon { display: inline-block; color: var(--lime); font-size: 16px; transform-origin: 50% 50%; }
.checkpoint-arrow b { display: block; font: 700 13px/1 var(--body); }
.checkpoint-arrow small { display: block; margin-top: 4px; color: var(--muted); font: 600 7px/1 var(--body); letter-spacing: .15em; }
.hud-bottom-left { position: absolute; left: max(26px, env(safe-area-inset-left)); bottom: max(28px, env(safe-area-inset-bottom)); display: flex; flex-direction: column; gap: 12px; }
.car-id { display: flex; align-items: center; gap: 12px; }
.small-badge { padding: 3px 7px; font-size: 9px; }
.car-id b { display: block; font: 800 20px/1 var(--display); letter-spacing: .03em; text-transform: uppercase; text-shadow: 0 2px 12px rgba(0,0,0,.5); }
.car-id small { display: block; margin-top: 5px; color: var(--muted); font: 600 8px/1 var(--body); letter-spacing: .17em; }
.hint-line { color: rgba(255,255,255,.36); font: 500 9px/1 var(--body); letter-spacing: .05em; }
.hud-bottom-right { position: absolute; right: max(30px, env(safe-area-inset-right)); bottom: max(24px, env(safe-area-inset-bottom)); }
.speed-cluster { width: 330px; text-align: right; filter: drop-shadow(0 8px 22px rgba(0,0,0,.5)); }
.drift-badge { display: inline-flex; align-items: baseline; gap: 9px; margin-bottom: 4px; padding: 6px 11px; border: 1px solid rgba(255,45,122,.5); background: rgba(255,45,122,.13); }
.drift-badge span { color: var(--pink); font: 700 9px/1 var(--body); letter-spacing: .18em; }
.drift-badge b { color: #fff; font: 800 20px/1 var(--display); }
.speed-main { display: flex; align-items: flex-end; justify-content: flex-end; gap: 9px; }
.speed-number { font: italic 800 104px/.8 var(--display); letter-spacing: -.02em; font-variant-numeric: tabular-nums; background: linear-gradient(180deg, #fff 30%, #d3d9dd 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.speed-unit { padding-bottom: 9px; text-align: left; }
.speed-unit span { display: block; color: rgba(255,255,255,.62); font: 700 10px/1 var(--body); letter-spacing: .15em; }
.speed-unit small { display: block; margin-top: 4px; color: rgba(255,255,255,.3); font: 600 8px/1 var(--body); letter-spacing: .08em; }
.gear-row { display: flex; align-items: center; justify-content: flex-end; gap: 13px; margin-top: 8px; }
.gear-box { display: flex; flex-direction: column; align-items: center; gap: 3px; min-width: 52px; padding: 7px 10px 6px; background: rgba(8,12,20,.55); border: 1px solid var(--line); }
.gear-box b { font: 800 30px/.9 var(--display); }
.gear-box span { color: var(--muted); font: 600 7px/1 var(--body); letter-spacing: .14em; }
.rpm-wrap { flex: 1; }
.rpm-bar { height: 7px; background: repeating-linear-gradient(90deg, rgba(255,255,255,.18) 0 4px, transparent 4px 7px); }
.rpm-bar i { display: block; height: 100%; width: 0; background: repeating-linear-gradient(90deg, var(--cyan) 0 4px, transparent 4px 7px); filter: drop-shadow(0 0 6px rgba(35,230,255,.55)); transition: width .05s linear; }
.nitro-row { display: flex; align-items: center; justify-content: flex-end; gap: 8px; margin-top: 8px; }
.nitro-row span { color: var(--muted); font: 600 7px/1 var(--body); letter-spacing: .16em; }
.nitro-bar { width: 132px; height: 3px; background: rgba(255,255,255,.13); transform: skewX(-18deg); }
.nitro-bar i { display: block; width: 100%; height: 100%; background: var(--lime); }
.center-feed { position: absolute; inset: 0; pointer-events: none; display: grid; place-items: center; }
.announce { text-align: center; animation: popIn .28s ease both; }
.announce small { display: block; margin-bottom: 5px; color: var(--lime); font: 700 10px/1 var(--body); letter-spacing: .3em; text-transform: uppercase; }
.announce b { font: italic 800 54px/1 var(--display); text-transform: uppercase; letter-spacing: .02em; text-shadow: 0 10px 40px rgba(0,0,0,.55); }
@keyframes popIn { from { opacity: 0; transform: translateY(14px) scale(.97); } to { opacity: 1; transform: none; } }
.countdown { font: italic 800 180px/.8 var(--display); color: var(--paper); text-shadow: 0 18px 60px rgba(0,0,0,.5); animation: countPulse .7s ease-out both; }
.countdown.go { color: var(--lime); }
@keyframes countPulse { from { opacity: 0; transform: scale(1.35); } 30% { opacity: 1; } to { opacity: 1; transform: scale(1); } }
.toast { position: absolute; top: 20%; left: 50%; transform: translateX(-50%); min-width: 220px; padding: 10px 20px; text-align: center; background: rgba(8,12,20,.72); border-left: 2px solid var(--cyan); backdrop-filter: blur(8px); animation: popIn .2s ease both; }
.toast b { display: block; font: 700 11px/1 var(--body); letter-spacing: .13em; }
.toast span { display: block; margin-top: 4px; color: var(--muted); font: 600 8px/1 var(--body); letter-spacing: .15em; }
.skill-popup { position: absolute; right: 31px; top: 43%; min-width: 190px; padding: 11px 15px; text-align: right; background: linear-gradient(90deg, transparent, rgba(8,12,20,.8)); border-right: 2px solid var(--pink); }
.skill-popup small { display: block; color: var(--pink); font: 700 8px/1 var(--body); letter-spacing: .22em; }
.skill-popup b { display: block; margin-top: 3px; font: italic 800 25px/1 var(--display); }
.skill-popup span { display: block; margin-top: 3px; color: var(--lime); font: 700 10px/1 var(--body); }
.wrong-way { position: absolute; top: 28%; left: 50%; transform: translateX(-50%); color: #ff5a5a; font: italic 800 40px/1 var(--display); letter-spacing: .05em; text-shadow: 0 4px 20px rgba(0,0,0,.6); animation: wrongPulse .5s alternate infinite; }
@keyframes wrongPulse { from { opacity: .5; } to { opacity: 1; } }
.hud-top-center-only { position: absolute; top: 22px; left: 50%; transform: translateX(-50%); color: rgba(255,255,255,.3); font: 600 8px/1 var(--body); letter-spacing: .16em; }

/* touch */
.touch-controls { position: absolute; inset: auto 0 max(16px, env(safe-area-inset-bottom)) 0; display: flex; align-items: flex-end; justify-content: space-between; padding: 0 max(18px, env(safe-area-inset-left)) 0 max(18px, env(safe-area-inset-right)); pointer-events: none; }
.touch-steer, .touch-pedals { display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.touch-btn { width: 72px; height: 72px; display: grid; place-items: center; border-radius: 50%; border: 1px solid rgba(255,255,255,.32); background: rgba(9,13,22,.5); color: rgba(255,255,255,.85); font: 800 16px/1 var(--body); backdrop-filter: blur(6px); touch-action: none; }
.touch-btn:active { background: rgba(255,45,122,.35); }
.touch-btn.gas { width: 86px; height: 86px; background: rgba(215,255,63,.17); border-color: rgba(215,255,63,.55); }
.touch-btn.brake { width: 66px; height: 66px; }
.touch-btn.tiny { width: 50px; height: 50px; font-size: 9px; letter-spacing: .05em; }
.touch-btn.nitro { border-color: rgba(35,230,255,.5); color: var(--cyan); }
.mobile-pause { position: absolute; top: max(16px, env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); width: 34px; height: 34px; border: 1px solid var(--line); background: rgba(9,13,22,.55); color: rgba(255,255,255,.7); font: 700 13px/1 var(--body); }

/* ----------------------------- garage ----------------------------- */
#garage {
  z-index: 20;
  background: radial-gradient(ellipse at 54% 50%, transparent 16%, rgba(5,8,14,.78) 75%),
              linear-gradient(90deg, rgba(5,8,14,.94) 0%, rgba(5,8,14,.45) 34%, rgba(5,8,14,.2) 55%, rgba(5,8,14,.85) 100%);
  display: flex; flex-direction: column; gap: 18px;
}
.modal-head { position: relative; display: flex; align-items: flex-start; justify-content: space-between; z-index: 2; }
.modal-head h2 { margin: 0; font: italic 800 44px/.9 var(--display); text-transform: uppercase; letter-spacing: .01em; }
.modal-head .eyebrow { margin-bottom: 7px; }
.garage-layout { position: relative; z-index: 2; flex: 1; display: grid; grid-template-columns: 340px 1fr 340px; gap: 22px; min-height: 0; }
.garage-list, .garage-detail { padding: 14px; overflow: hidden; display: flex; flex-direction: column; }
.garage-list-head { display: flex; justify-content: space-between; padding: 2px 3px 11px; border-bottom: 1px solid var(--line); color: rgba(255,255,255,.54); font: 700 9px/1 var(--body); letter-spacing: .16em; }
.garage-list-head small { color: rgba(255,255,255,.26); font-size: 7px; letter-spacing: .14em; }
.car-list { overflow-y: auto; padding: 8px 4px 8px 0; scrollbar-width: thin; scrollbar-color: rgba(255,255,255,.22) transparent; }
.car-list::-webkit-scrollbar { width: 4px; }
.car-list::-webkit-scrollbar-thumb { background: rgba(255,255,255,.22); }
.car-item { position: relative; display: grid; grid-template-columns: 30px 1fr auto; align-items: center; gap: 10px; width: 100%; padding: 11px 10px; margin-bottom: 4px; text-align: left; border-left: 2px solid transparent; transition: .15s; }
.car-item:hover { background: rgba(255,255,255,.05); }
.car-item.active { background: linear-gradient(90deg, rgba(255,45,122,.17), transparent); border-left-color: var(--pink); }
.car-item .num { color: rgba(255,255,255,.25); font: 700 10px/1 var(--body); }
.car-item b { display: block; font: 700 13px/1 var(--body); letter-spacing: .03em; }
.car-item small { display: block; margin-top: 4px; color: rgba(255,255,255,.35); font: 500 8px/1 var(--body); letter-spacing: .1em; text-transform: uppercase; }
.car-item .kl { color: var(--lime); font: 700 9px/1 var(--body); }
.garage-center { position: relative; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 20px; pointer-events: none; }
.garage-caption { display: flex; align-items: center; gap: 12px; padding: 8px 12px; background: rgba(8,12,20,.35); border: 1px solid var(--line); }
.garage-caption span { font: italic 800 24px/1 var(--display); color: var(--pink); }
.garage-caption small { color: rgba(255,255,255,.4); font: 600 7px/1 var(--body); letter-spacing: .15em; }
.garage-detail h2 { margin: 10px 0 3px; font: italic 800 48px/.86 var(--display); text-transform: uppercase; }
.garage-detail #garageMeta { margin: 0 0 18px; color: var(--muted); font: 600 9px/1 var(--body); letter-spacing: .15em; text-transform: uppercase; }
.stat-list.large { gap: 9px; }
.stat-list.large .stat { grid-template-columns: 76px 1fr 24px; }
.stat-list.large .bar i { height: 6px; }
.paint-block { margin-top: 19px; }
.paint-block > span { color: rgba(255,255,255,.4); font: 700 8px/1 var(--body); letter-spacing: .18em; }
.paint-block .swatches { margin: 9px 0 0; }
.spec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; margin-top: 18px; background: var(--line); border: 1px solid var(--line); }
.spec-grid > div { padding: 9px 10px; background: rgba(8,12,20,.7); }
.spec-grid small { display: block; color: rgba(255,255,255,.32); font: 600 7px/1 var(--body); letter-spacing: .14em; }
.spec-grid b { display: block; margin-top: 4px; font: 700 12px/1 var(--body); }
.garage-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 16px; }
.garage-actions .btn { flex: 1; padding: 0 16px; font-size: 10px; }

/* ------------------------------- map ------------------------------ */
#mapscreen { z-index: 25; background: rgba(5,8,14,.9); backdrop-filter: blur(10px); display: flex; flex-direction: column; gap: 16px; }
.map-layout { flex: 1; min-height: 0; display: grid; grid-template-columns: 1fr 360px; gap: 18px; }
.map-frame { position: relative; min-height: 0; display: grid; place-items: center; padding: 12px; overflow: hidden; }
#bigMap { display: block; width: min(100%, calc(100vh - 150px)); height: auto; max-height: 100%; aspect-ratio: 1; border: 1px solid rgba(255,255,255,.16); }
#bigMapMarkers { position: absolute; inset: 0; pointer-events: none; }
.map-marker { position: absolute; transform: translate(-50%, -50%); display: grid; place-items: center; width: 24px; height: 24px; border-radius: 50%; background: rgba(10,14,23,.8); border: 2px solid var(--pink); box-shadow: 0 0 14px rgba(255,45,122,.5); font: 700 9px/1 var(--body); pointer-events: auto; cursor: pointer; }
.map-marker:hover { transform: translate(-50%,-50%) scale(1.18); }
.map-marker.player { width: 16px; height: 16px; background: var(--lime); border-color: var(--lime); box-shadow: 0 0 12px var(--lime); }
.map-marker.fest { border-color: var(--cyan); background: rgba(35,230,255,.25); }
.map-marker.town { width: 12px; height: 12px; border-color: var(--orange); box-shadow: none; }
.map-marker.active { border-color: var(--lime); box-shadow: 0 0 20px rgba(215,255,63,.65); }
.map-legend { position: absolute; left: 22px; bottom: 20px; display: flex; flex-wrap: wrap; gap: 13px; padding: 8px 11px; background: rgba(8,12,20,.62); border: 1px solid var(--line); color: rgba(255,255,255,.55); font: 600 8px/1 var(--body); letter-spacing: .05em; }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.lg { display: inline-block; width: 7px; height: 7px; border-radius: 50%; }
.lg.player { background: var(--lime); } .lg.race { background: var(--pink); } .lg.fest { background: var(--cyan); } .lg.town { background: var(--orange); }
.map-side { display: flex; flex-direction: column; padding: 14px; overflow: hidden; }
.event-list { flex: 1; overflow-y: auto; padding: 8px 3px 8px 0; }
.event-item { display: flex; flex-direction: column; width: 100%; padding: 12px 12px 11px; margin-bottom: 7px; text-align: left; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.03); transition: .15s; }
.event-item:hover { border-color: rgba(255,255,255,.32); background: rgba(255,255,255,.06); }
.event-item .event-top { display: flex; justify-content: space-between; align-items: center; }
.event-item b { font: 700 13px/1 var(--body); letter-spacing: .03em; }
.event-item .badge { padding: 3px 6px; background: rgba(215,255,63,.15); color: var(--lime); font: 700 7px/1 var(--body); letter-spacing: .14em; }
.event-item small { margin-top: 6px; color: rgba(255,255,255,.38); font: 500 8px/1 var(--body); letter-spacing: .1em; text-transform: uppercase; }
.event-item .event-meta { display: flex; gap: 13px; margin-top: 8px; color: rgba(255,255,255,.55); font: 600 8px/1 var(--body); letter-spacing: .08em; }
.event-item .event-meta i { color: var(--cyan); font-style: normal; }
.map-side-foot { display: flex; gap: 8px; padding-top: 13px; border-top: 1px solid var(--line); }
.map-side-foot .btn { flex: 1; padding: 0 12px; }

/* ------------------------------ pause ----------------------------- */
.modal-layer { z-index: 30; display: grid; place-items: center; background: rgba(5,8,14,.72); backdrop-filter: blur(10px); }
.pause-panel { width: min(560px, 92vw); padding: 26px 28px 22px; border-top: 2px solid var(--pink); }
.pause-head { position: relative; padding-bottom: 15px; border-bottom: 1px solid var(--line); }
.pause-head h2 { margin: 0; font: italic 800 52px/.9 var(--display); text-transform: uppercase; }
.pause-head > p:last-child { margin: 6px 0 0; color: var(--muted); font: 600 9px/1 var(--body); letter-spacing: .14em; }
.pause-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 18px 0; }
.pause-actions .btn { height: 46px; padding: 0 14px; font-size: 10px; }
.pause-actions .btn:first-child { grid-column: 1 / -1; }
.pause-settings { display: flex; flex-direction: column; gap: 12px; padding-top: 14px; border-top: 1px solid var(--line); }
.setting { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.setting > span { color: rgba(255,255,255,.42); font: 700 8px/1 var(--body); letter-spacing: .18em; }
.time-tabs { display: flex; gap: 4px; }
.time-tabs button { padding: 7px 10px; color: rgba(255,255,255,.45); font: 700 8px/1 var(--body); letter-spacing: .09em; border: 1px solid rgba(255,255,255,.13); }
.time-tabs button.active { color: #0a0e16; background: var(--cyan); border-color: var(--cyan); }
.toggle-btn { min-width: 56px; padding: 7px 12px; color: var(--lime); font: 700 8px/1 var(--body); letter-spacing: .12em; border: 1px solid rgba(215,255,63,.35); }
.pause-tip { margin: 16px 0 0; color: rgba(255,255,255,.3); font: 500 10px/1.5 var(--body); }

/* ----------------------------- results ---------------------------- */
#results { z-index: 35; }
.result-panel { width: min(600px, 92vw); padding: 26px 30px 24px; text-align: center; border-top: 2px solid var(--lime); }
.result-panel .eyebrow { justify-content: center; }
.medal { font-size: 58px; line-height: 1; margin: 6px 0 8px; filter: drop-shadow(0 6px 20px rgba(0,0,0,.4)); }
.result-panel h2 { margin: 0; font: italic 800 40px/.9 var(--display); text-transform: uppercase; }
.result-time { margin: 12px 0 16px; color: var(--lime); font: 800 54px/.9 var(--display); font-variant-numeric: tabular-nums; }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); }
.result-stats > div { padding: 10px; background: rgba(8,12,20,.6); }
.result-stats small { display: block; color: rgba(255,255,255,.35); font: 600 7px/1 var(--body); letter-spacing: .14em; }
.result-stats b { display: block; margin-top: 5px; font: 700 12px/1 var(--body); }
.result-actions { display: flex; gap: 8px; margin-top: 18px; }
.result-actions .btn { flex: 1; }

/* ------------------------------ misc ------------------------------ */
.rotate-hint { position: fixed; left: 50%; bottom: 90px; transform: translateX(-50%); z-index: 60; padding: 8px 14px; background: rgba(8,12,20,.8); border: 1px solid var(--line); color: rgba(255,255,255,.7); font: 600 9px/1 var(--body); letter-spacing: .1em; }

/* --------------------------- responsive --------------------------- */
