  glass: new THREE.MeshStandardMaterial({ color: 0x09131d, metalness: 0.9, roughness: 0.1, transparent: true, opacity: 0.92 }),
  dark: new THREE.MeshStandardMaterial({ color: 0x11151a, roughness: 0.72, metalness: 0.18 }),
