import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim()
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'))
const browser = await chromium.launch(config.browser.launchOptions)

async function newMobile(viewport) {
  const p = await browser.newPage({ viewport, isMobile:true, hasTouch:true, deviceScaleFactor:1 })
  p.on('pageerror', e=>console.log('ERR', viewport.width+'x'+viewport.height, e.message))
  p.on('console', c=>{ if(c.type()==='error') console.log('CONSOLE', viewport.width+'x'+viewport.height, c.text()) })
  await p.goto('http://localhost:3003', {waitUntil:'load'})
  await p.waitForFunction(()=>window.__game && !document.querySelector('#title').classList.contains('hidden'), null, {timeout:60000})
  return p
}

async function checkOverflow(p, label) {
  const info = await p.evaluate(() => {
    const doc = document.documentElement
    const bad = []
    for (const el of document.querySelectorAll('#title *, #garage *, #mapscreen *, #hud *')) {
      const r = el.getBoundingClientRect()
      if (r.width === 0 || r.height === 0) continue
      if (r.right > innerWidth + 1.5 || r.bottom > innerHeight + 1.5 || r.left < -1.5 || r.top < -1.5) {
        if (el.offsetParent !== null) bad.push({ tag: el.tagName, id: el.id, cls: el.className?.toString?.().slice(0,50), r: [Math.round(r.left), Math.round(r.top), Math.round(r.right), Math.round(r.bottom)] })
      }
    }
    return { vw: innerWidth, vh: innerHeight, scrollW: doc.scrollWidth, scrollH: doc.scrollHeight, bad: bad.slice(0, 12) }
  })
  console.log('OVERFLOW', label, JSON.stringify(info))
}

for (const vp of [{width:390,height:844},{width:844,height:390}]) {
  const label = vp.width+'x'+vp.height
  const p = await newMobile(vp)
  await p.waitForTimeout(700)
  await p.screenshot({path:`/tmp/qa-${label}-title.png`})
  await checkOverflow(p, label+' title')
  await p.evaluate(()=>__game.openGarage())
  await p.waitForTimeout(900)
  await p.screenshot({path:`/tmp/qa-${label}-garage.png`})
  await checkOverflow(p, label+' garage')
  await p.evaluate(()=>document.querySelector('#btnGarageClose').click())
  await p.waitForTimeout(400)
  await p.evaluate(()=>__game.openMap())
  await p.waitForTimeout(900)
  await p.screenshot({path:`/tmp/qa-${label}-map.png`})
  await checkOverflow(p, label+' map')
  await p.evaluate(()=>document.querySelector('#btnMapClose').click())
  await p.waitForTimeout(300)
  await p.locator('#btnPlay').click()
  await p.waitForTimeout(1000)
  await p.screenshot({path:`/tmp/qa-${label}-drive.png`})
  await checkOverflow(p, label+' drive')
  // touch controls: hold gas, then steer
  const gas = p.locator('[data-touch="gas"]')
  const box = await gas.boundingBox()
  if (box) {
    await p.mouse.move(box.x+box.width/2, box.y+box.height/2)
    await p.mouse.down()
    await p.waitForTimeout(120)
    const active = await p.evaluate(()=>document.querySelector('[data-touch="gas"]').classList.contains('active'))
    await p.waitForTimeout(1800)
    await p.mouse.up()
    const speed = await p.evaluate(()=>({ kmh:+document.querySelector('#speedNumber').textContent, gear:document.querySelector('#gearNumber').textContent }))
    console.log('TOUCH GAS', label, {active, speed})
  } else {
    console.log('TOUCH GAS', label, 'NO BOX')
  }
  await p.locator('#btnPauseMobile').click()
  await p.waitForTimeout(500)
  await p.screenshot({path:`/tmp/qa-${label}-pause.png`})
  await p.close()
}
await browser.close()

