import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const runtime = '/home/runner/.local/share/omgithub-playwright'
process.env.DISPLAY ||= ':' + readFileSync(runtime + '/display','utf8').trim()
const require = createRequire(runtime + '/package.json')
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(runtime + '/linux.json','utf8'))
const browser = await chromium.launch(config.browser.launchOptions)

async function open(viewport, mobile) {
  const p = await browser.newPage({ viewport, isMobile: mobile, hasTouch: mobile, deviceScaleFactor:1 })
  p.on('pageerror', e=>console.log('ERR', viewport.width+'x'+viewport.height, e.message))
  p.on('console', c=>{ if(c.type()==='error') console.log('CONSOLE', viewport.width+'x'+viewport.height, c.text()) })
  await p.goto('http://localhost:3003', {waitUntil:'load'})
  await p.waitForFunction(()=>window.__game && !document.querySelector('#title').classList.contains('hidden'), null, {timeout:60000})
  return p
}

const m = await open({width:390,height:844}, true)
